# Package code: NAMESPACE needs useDynLib(datamungerNN, .registration = TRUE), importFrom(R6, R6Class),
# S3method(Ops, RosettaObject, .rosetta_ops); .onLoad() must call .rosetta_onload().
.rosetta_object <- R6::R6Class("RosettaObject", cloneable = FALSE, public = list(
  .ptr = NULL,
  close = function() { .Call(`.rs_release`, self); invisible(NULL) },
  print = function(...) { cat("<", class(self)[[1L]], ">\n", sep = ""); invisible(self) }
))
.rosetta_ops <- function(e1, e2) {
  unary <- missing(e2)
  name <- switch(.Generic, "+" = if (unary) "__pos__" else "__add__", "-" = if (unary) "__neg__" else "__sub__",
    "*" = "__mul__", "/" = "__truediv__", "%%" = "__mod__", "==" = "__eq__", "!=" = "__ne__", "<" = "__lt__",
    "<=" = "__le__", ">" = "__gt__", ">=" = "__ge__", "&" = "__and__", "|" = "__or__", "!" = "__not__", NULL)
  method <- if (!is.null(name) && inherits(e1, "RosettaObject")) e1[[name]] else NULL
  if (!is.function(method)) {
    if (.Generic %in% c("==", "!=") && !unary && inherits(e1, "RosettaObject") && inherits(e2, "RosettaObject"))
      return((.Generic == "==") == identical(e1, e2))
    stop("operator ", .Generic, " is not defined for ", class(e1)[[1L]])
  }
  if (unary) method() else method(e2)
}
.rosetta_callable <- function(ptr) { force(ptr); function(...) .Call(`.rs_invoke`, ptr, list(...)) }
#' A mutable cell for C++ reference parameters
#'
#' A native function that takes a non-const C++ reference updates `x$value` when called with
#' `x <- rosetta_ref(value)`; plain R values are passed by copy.
#'
#' @param value The initial value.
#' @return An environment of class `rosetta_ref` holding `value`.
#' @md
rosetta_ref <- function(value = NULL) {
  ref <- new.env(parent = emptyenv())
  ref$value <- value
  class(ref) <- "rosetta_ref"
  ref
}
# The R6 subclass override of a virtual method, or NULL where the generated native method applies.
.rosetta_override <- function(self, name) {
  method <- get0(name, envir = self, inherits = FALSE)
  if (!is.function(method)) return(NULL)
  code <- body(method)
  if (is.call(code) && identical(code[[1L]], quote(invisible))) code <- code[[2L]]
  native <- is.call(code) && identical(code[[1L]], quote(.Call)) && is.name(code[[2L]]) && startsWith(as.character(code[[2L]]), ".rs_")
  if (native) NULL else method
}
