#' ```cpp
#' namespace n = dm::nn;
#' n::ParameterStore p(17), state(17);
#' n::models::ResNetNormConfig norm;
#' norm.scale = true;
#' const auto fused = n::models::HRFuse(
#'     p, state, "exchange", {n::ones({1, 5, 7, 2}), n::ones({1, 3, 4, 4})}, {2, 4}, norm);
#' ```
