#' n::models::YolactConfig c;
#' c.size = 64;
#' c.classes = 10;
#' c.depth = 18;
#' c.divisor = 8;
#' c.width = 32;
#' c.prototypes = 8;
#' c.grayscale = true;
#' const auto net = n::models::Yolact(p, state, n::zeros({1, 64, 64, 1}), c);
#' const auto masks =
