    `fake_probability` = function(value) if (missing(value)) .Call(`.rs_2036`, self) else invisible(.Call(`.rs_2037`, self, value)),
    `discriminator_loss` = function(value) if (missing(value)) .Call(`.rs_2038`, self) else invisible(.Call(`.rs_2039`, self, value)),
