    `encoded` = function(value) if (missing(value)) .Call(`.rs_2061`, self) else invisible(.Call(`.rs_2062`, self, value)),
    `real_score` = function(value) if (missing(value)) .Call(`.rs_2063`, self) else invisible(.Call(`.rs_2064`, self, value)),
    `fake_score` = function(value) if (missing(value)) .Call(`.rs_2065`, self) else invisible(.Call(`.rs_2066`, self, value)),
    `discriminator_loss` = function(value) if (missing(value)) .Call(`.rs_2067`, self) else invisible(.Call(`.rs_2068`, self, value)),
    `eg_loss` = function(value) if (missing(value)) .Call(`.rs_2069`, self) else invisible(.Call(`.rs_2070`, self, value)),
