    `continuous` = function(value) if (missing(value)) .Call(`.rs_2123`, self) else invisible(.Call(`.rs_2124`, self, value)),
    `total` = function(value) if (missing(value)) .Call(`.rs_2125`, self) else invisible(.Call(`.rs_2126`, self, value)),
    `lower_bound` = function(value) if (missing(value)) .Call(`.rs_2127`, self) else invisible(.Call(`.rs_2128`, self, value))
  )
