    `real_score` = function(value) if (missing(value)) .Call(`.rs_2353`, self) else invisible(.Call(`.rs_2354`, self, value)),
    `fake_score` = function(value) if (missing(value)) .Call(`.rs_2355`, self) else invisible(.Call(`.rs_2356`, self, value)),
    `interpolation` = function(value) if (missing(value)) .Call(`.rs_2357`, self) else invisible(.Call(`.rs_2358`, self, value)),
    `input_gradient` = function(value) if (missing(value)) .Call(`.rs_2359`, self) else invisible(.Call(`.rs_2360`, self, value)),
    `symbolic_input_gradient` = function(value) if (missing(value)) .Call(`.rs_2361`, self) else invisible(.Call(`.rs_2362`, self, value)),
    `norm` = function(value) if (missing(value)) .Call(`.rs_2363`, self) else invisible(.Call(`.rs_2364`, self, value)),
