#' const auto out=n::models::HierarchicalVariationalAutoencoder(
#'     p,state,n::zeros({2,784}),n::zeros({2,51}),true);
#' // Default NVAE:37 trainable tensors/2027 scalars plus six BN moving buffers.
#' ```
