    `reconstruction` = function(value) if (missing(value)) .Call(`.rs_5936`, self) else invisible(.Call(`.rs_5937`, self, value)),
    `real_score` = function(value) if (missing(value)) .Call(`.rs_5938`, self) else invisible(.Call(`.rs_5939`, self, value)),
    `fake_score` = function(value) if (missing(value)) .Call(`.rs_5940`, self) else invisible(.Call(`.rs_5941`, self, value)),
    `d_loss` = function(value) if (missing(value)) .Call(`.rs_5942`, self) else invisible(.Call(`.rs_5943`, self, value)),
    `g_loss` = function(value) if (missing(value)) .Call(`.rs_5944`, self) else invisible(.Call(`.rs_5945`, self, value)),
    `adversarial_loss` = function(value) if (missing(value)) .Call(`.rs_5946`, self) else invisible(.Call(`.rs_5947`, self, value)),
    `reconstruction_loss` = function(value) if (missing(value)) .Call(`.rs_5948`, self) else invisible(.Call(`.rs_5949`, self, value))
  )
