    `stage_divergence0` = function(value) if (missing(value)) .Call(`.rs_6507`, self) else invisible(.Call(`.rs_6508`, self, value)),
    `stage_velocity0` = function(value) if (missing(value)) .Call(`.rs_6509`, self) else invisible(.Call(`.rs_6510`, self, value)),
    `stage1` = function(value) if (missing(value)) .Call(`.rs_6511`, self) else invisible(.Call(`.rs_6512`, self, value)),
    `stage_logdet1` = function(value) if (missing(value)) .Call(`.rs_6513`, self) else invisible(.Call(`.rs_6514`, self, value)),
    `stage_divergence1` = function(value) if (missing(value)) .Call(`.rs_6515`, self) else invisible(.Call(`.rs_6516`, self, value)),
    `stage_velocity1` = function(value) if (missing(value)) .Call(`.rs_6517`, self) else invisible(.Call(`.rs_6518`, self, value)),
    `stage2` = function(value) if (missing(value)) .Call(`.rs_6519`, self) else invisible(.Call(`.rs_6520`, self, value)),
