  public = list(
    initialize = function(...) {
      if (...length() == 1L && inherits(..1, "rosetta_ptr")) self$.ptr <- ..1
      else { if (!is.null(self$.ptr)) stop("native object already initialized"); self$.ptr <- .Call(`.rs_6557`, list(...)) }
      invisible(self)
