    `checkerboard_support_fraction` = function(value) if (missing(value)) .Call(`.rs_6549`, self) else invisible(.Call(`.rs_6550`, self, value)),
    `fraction_near_modes` = function(value) if (missing(value)) .Call(`.rs_6551`, self) else invisible(.Call(`.rs_6552`, self, value)),
