    `alpha_bar` = function(value) if (missing(value)) .Call(`.rs_6562`, self) else invisible(.Call(`.rs_6563`, self, value)),
    `alpha_bar_previous` = function(value) if (missing(value)) .Call(`.rs_6564`, self) else invisible(.Call(`.rs_6565`, self, value)),
    `sqrt_alpha_bar` = function(value) if (missing(value)) .Call(`.rs_6566`, self) else invisible(.Call(`.rs_6567`, self, value)),
    `sqrt_one_minus_alpha_bar` = function(value) if (missing(value)) .Call(`.rs_6568`, self) else invisible(.Call(`.rs_6569`, self, value)),
